WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), order_date) AS days_since_order_date, COALESCE(channel, 'unassigned') AS channel_filled FROM orders WHERE order_date > DATE '2023-10-26' AND store_id IS NOT NULL AND status IN ('PENDING', 'RETURNED', 'COMPLETED')) SELECT id, customer_id FROM base EXCEPT DISTINCT SELECT id, customer_id FROM orders WHERE customer_id IN (7, 14, 26, 32)
